          "format": "text",
          "fields": {
            "text": "甲站报告核验正文，包含来源编号、已知事实、可支持结论、未知事项，不与乙站比较"
          }
        },
        "capability": {
          "difficulty": "medium",
          "risk": "low",
          "input_budget_tokens": 16384,
          "expected_output_tokens": 1200
        },
        "checks": [
          "核验正文只针对甲站报告，不与乙站作优劣比较",
          "保留S1、S3、S4等来源编号",
          "区分已知事实、可支持结论、建议和未知事项",
          "未虚构未回应人数、总体规模、原始答卷或已执行操作",
          "未据百分比直接认定甲服务更好"
